Given a string s consisting of lowercase letters and parentheses '(' and ')'.A string is considered valid if:Every opening parenthesis '(' has a corresponding closing parenthesis ')'.Parentheses are properly nested.Remove the minimum number of invalid parentheses from s so that the resulting string becomes valid.  Return all the possible distinct valid strings in lexicographically sorted order.Examples:Input: s = "()())()"Output: ["(())()", "()()()"]Explanation: The string "()())()" has one extra ')', making it invalid. By removing one ')', we can make it valid in two ways:Remove the 1st index ')' -> "(())()"Remove the 4th index ')' -> "()()()"Both are valid and require the minimum removals.Input: s = "(a)())()"Output: ["(a())()", "(a)()()"]Explanation: We remove one ')' (minimum removals) to make it valid. Possible valid results:Remove a ')' -> "(a())()"Remove another ')' -> "(a)()()"Input: s = ")("Output: [""]Explanation: The string ")(" is invalid. Removing both parentheses (minimum removals) gives an empty string "", which is valid.Try It YourselfTable of ContentBreadth First Search (BFS) - O(2 ^ n) Time and O(2 ^ n) SpaceDepth First Search (DFS) - O(2 ^ n) Time and O(2 ^ n) SpaceBreadth First Search (BFS) - O(2 ^ n) Time and O(2 ^ n) SpaceThe idea is to remove parentheses one by one and check whether the string is valid. BFS helps find the valid strings with the minimum removals.Process strings level by level using a queue.  At each level, we have one less character compared to the previous level.Stop when a valid string is found and store all valid strings at that level.Use a visited set to avoid duplicate strings.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Check whether the given string has valid parentheses.
bool isValid(string s)
{
    int count = 0;

    // Traverse the string.
    for (char c : s)
    {

        // Increment for an opening parenthesis.
        if (c == '(')
            count++;

        // Decrement for a closing parenthesis.
        else if (c == ')')
        {
            count--;

            // More closing parentheses than opening ones.
            if (count < 0)
                return false;
        }
    }

    // Valid only when all opening parentheses are matched.
    return count == 0;
}

// Remove the minimum number of invalid parentheses.
vector<string> validParenthesis(string &s)
{

    // Store strings that have already been visited.
    unordered_set<string> visited;

    // Queue for BFS.
    queue<string> q;

    // Store all valid strings.
    vector<string> res;

    // Push the original string.
    q.push(s);

    // Mark the original string as visited.
    visited.insert(s);

    // Indicates that a valid string has been found.
    bool found = false;

    // Perform BFS.
    while (!q.empty())
    {

        // Get the current string.
        string curr = q.front();
        q.pop();

        // Check whether the current string is valid.
        if (isValid(curr))
        {
            res.push_back(curr);
            found = true;
        }

        // Do not generate the next level after
        // finding a valid string.
        if (found)
            continue;

        // Try removing each parenthesis.
        for (int i = 0; i < curr.length(); i++)
        {

            // Skip normal characters.
            if (curr[i] != '(' && curr[i] != ')')
                continue;

            // Remove the parenthesis at index i.
            string next = curr.substr(0, i) + curr.substr(i + 1);

            // Process only unvisited strings.
            if (visited.find(next) == visited.end())
            {
                visited.insert(next);
                q.push(next);
            }
        }
    }

    // Sort the valid strings lexicographically.
    sort(res.begin(), res.end());

    return res;
}

int main()
{

    string s = "(a)())()";

    vector<string> res = validParenthesis(s);

    cout << "[";

    for (int i = 0; i < res.size(); i++)
    {

        if (i > 0)
            cout << ", ";

        cout << "\"" << res[i] << "\"";
    }

    cout << "]";

    return 0;
}


